import { DynamoDBClient } from '@aws-sdk/client-dynamodb';
import { DynamoDBDocumentClient, PutCommand, GetCommand, QueryCommand, DeleteCommand } from '@aws-sdk/lib-dynamodb';

const client = new DynamoDBClient({ region: 'ap-south-1' });
const db = DynamoDBDocumentClient.from(client);

// PUT — create or replace an item
await db.send(new PutCommand({
  TableName: 'MyAppTable',
  Item: {
    PK: 'USER#u001',
    SK: 'PROFILE',
    name: 'Alice',
    email: 'alice@example.com',
    createdAt: new Date().toISOString(),
  },
}));

// GET — retrieve a specific item (must know PK + SK)
const response = await db.send(new GetCommand({
  TableName: 'MyAppTable',
  Key: { PK: 'USER#u001', SK: 'PROFILE' },
}));
console.log(response.Item?.name);  // 'Alice'

// QUERY — get all items with the same partition key
// Get all orders for user u001
const orders = await db.send(new QueryCommand({
  TableName: 'MyAppTable',
  KeyConditionExpression: 'PK = :pk AND begins_with(SK, :sk)',
  ExpressionAttributeValues: {
    ':pk': 'USER#u001',
    ':sk': 'ORDER#',
  },
}));
console.log(orders.Items);  // all order items for u001

// DELETE
await db.send(new DeleteCommand({
  TableName: 'MyAppTable',
  Key: { PK: 'USER#u001', SK: 'ORDER#2026-01-15' },
}));
